/* arxiviq — Ava MLOps console.
 * Data strategy: prefer live GitHub fetches (raw contents + releases API); fall back to the
 * baked snapshot generated by arxiviq/generate_data.py. The source badge always states which
 * one the viewer is looking at — the console renders published numbers, it never invents them.
 */
"use strict";

const GH = {
  factoryRaw: (path) =>
    `https://raw.githubusercontent.com/jcdavis131/ava-agi-factory-v6-4/main/${path}`,
  rtxReleases: "https://api.github.com/repos/jcdavis131/scout-rtx/releases?per_page=5",
};
const POLL_MS = 60_000;

const state = {
  snapshot: null,        // baked snapshot.json
  cards: null,           // baked model-cards.json
  live: { status: null, experiments: null },
  branch: "base",
  source: "loading",
};

/* ---------------- data loading ---------------- */

async function fetchJson(url, opts = {}) {
  const res = await fetch(url, { cache: "no-store", ...opts });
  if (!res.ok) throw new Error(`${res.status} ${url}`);
  return res.json();
}

async function loadBaked() {
  [state.snapshot, state.cards] = await Promise.all([
    fetchJson("data/snapshot.json"),
    fetchJson("data/model-cards.json"),
  ]);
}

async function tryLive() {
  let anyLive = false;
  try {
    state.live.status = await fetchJson(GH.factoryRaw("STATUS.json"));
    anyLive = true;
  } catch { /* private repo or offline — snapshot covers it */ }
  try {
    const releases = await fetchJson(GH.rtxReleases);
    const asset = releases.flatMap((r) => r.assets || [])
      .find((a) => a.name === "results.jsonl");
    if (asset) {
      const text = await (await fetch(asset.browser_download_url, { cache: "no-store" })).text();
      state.live.experiments = text.trim().split("\n").flatMap((line) => {
        try { const row = JSON.parse(line); return row.val_bpb != null ? [row] : []; }
        catch { return []; }
      });
      anyLive = anyLive || state.live.experiments.length > 0;
    }
  } catch { /* same */ }
  state.source = anyLive ? "live" : "snapshot";
  renderSourceBadge();
}

/* ---------------- shared UI ---------------- */

const $ = (sel) => document.querySelector(sel);

function renderSourceBadge() {
  const el = $("#source-badge");
  el.classList.remove("live", "snapshot");
  if (state.source === "live") {
    el.classList.add("live");
    el.textContent = "live · GitHub";
  } else {
    el.classList.add("snapshot");
    const at = state.snapshot?.generated_at || "unknown";
    el.textContent = `snapshot · baked ${at.slice(0, 10)}`;
  }
  $("#generated-at").textContent =
    `data snapshot generated ${state.snapshot?.generated_at || "—"}`;
}

const tooltip = {
  el: null,
  show(html, x, y) {
    this.el.innerHTML = html;
    this.el.classList.remove("hidden");
    const pad = 14;
    const w = this.el.offsetWidth, h = this.el.offsetHeight;
    this.el.style.left = Math.min(x + pad, window.innerWidth - w - 8) + "px";
    this.el.style.top = Math.max(8, Math.min(y + pad, window.innerHeight - h - 8)) + "px";
  },
  hide() { this.el.classList.add("hidden"); },
};

function chip(kind, label) {
  return `<span class="chip ${kind}"><span class="dot"></span>${label}</span>`;
}

function statusChip(pass) {
  return pass ? chip("good", "PASS") : chip("critical", "FAIL");
}

/* ---------------- telemetry ---------------- */

function renderTelemetry() {
  const status = state.live.status || null;
  const pipe = status
    ? {
        current_phase: status.builder?.current_phase,
        phase_progress: status.builder?.phase_progress,
        total_shards: status.builder?.total_shards,
        trainer_steps: status.trainer?.steps,
        trainer_loss: status.trainer?.loss,
        weekly_training: status.weekly_training?.status ?? status.weekly_training,
      }
    : state.snapshot.pipeline;
  const exps = state.live.experiments || [];
  const best = exps.length ? Math.min(...exps.map((e) => e.val_bpb)) : null;

  const weekly = String(pipe.weekly_training ?? "unknown");
  const weeklyKind = weekly.startsWith("BLOCKED") ? "critical"
    : weekly.toLowerCase().includes("run") ? "good" : "warning";

  $("#telemetry-tiles").innerHTML = `
    <div class="tile"><div class="k">Pipeline phase</div>
      <div class="v">${pipe.current_phase ?? "—"}</div>
      <div class="d">progress ${pipe.phase_progress != null ? Math.round(pipe.phase_progress * 100) + "%" : "—"} · ${pipe.total_shards ?? "—"} shards</div></div>
    <div class="tile"><div class="k">Trainer</div>
      <div class="v">${pipe.trainer_steps ?? "—"}<span class="unit">steps</span></div>
      <div class="d">loss ${pipe.trainer_loss ?? "—"}</div></div>
    <div class="tile"><div class="k">Weekly training</div>
      <div class="v" style="font-size:15px; margin-top:6px">${chip(weeklyKind, weekly)}</div></div>
    <div class="tile"><div class="k">RTX experiments</div>
      <div class="v">${exps.length || "—"}</div>
      <div class="d">${best != null ? `best val_bpb ${best.toFixed(4)}` : "release feed unreachable"}</div></div>`;

  renderBpbChart(exps);
  $("#telemetry-note").textContent = exps.length
    ? `${exps.length} experiments from scout-rtx releases · polling every 60s`
    : "";
}

function renderBpbChart(exps) {
  const host = $("#bpb-chart"), empty = $("#bpb-empty");
  if (!exps.length) {
    host.innerHTML = "";
    empty.classList.remove("hidden");
    empty.textContent = "No live experiment feed (scout-rtx releases unreachable from this browser). "
      + "The telemetry tiles above fall back to the baked pipeline snapshot.";
    return;
  }
  empty.classList.add("hidden");
  const W = Math.max(640, host.clientWidth || 640), H = 260;
  const m = { l: 56, r: 16, t: 12, b: 28 };
  const xs = exps.map((_, i) => i);
  const ys = exps.map((e) => e.val_bpb);
  const yMin = Math.min(...ys), yMax = Math.max(...ys);
  const yPad = (yMax - yMin || 0.01) * 0.12;
  const y0 = yMin - yPad, y1 = yMax + yPad;
  const X = (i) => m.l + (i / Math.max(1, xs.length - 1)) * (W - m.l - m.r);
  const Y = (v) => m.t + (1 - (v - y0) / (y1 - y0)) * (H - m.t - m.b);

  const yTicks = 4;
  let grid = "", labels = "";
  for (let i = 0; i <= yTicks; i++) {
    const v = y0 + (i / yTicks) * (y1 - y0);
    grid += `<line class="gridline" x1="${m.l}" x2="${W - m.r}" y1="${Y(v)}" y2="${Y(v)}"/>`;
    labels += `<text x="${m.l - 8}" y="${Y(v) + 4}" text-anchor="end">${v.toFixed(3)}</text>`;
  }
  const path = ys.map((v, i) => `${i ? "L" : "M"}${X(i).toFixed(1)},${Y(v).toFixed(1)}`).join(" ");
  const bestIdx = ys.indexOf(Math.min(...ys));
  const markers = `<circle class="dot-marker" r="4" cx="${X(bestIdx)}" cy="${Y(ys[bestIdx])}"/>
    <text class="val-label" x="${X(bestIdx)}" y="${Y(ys[bestIdx]) - 10}" text-anchor="middle">best ${ys[bestIdx].toFixed(4)}</text>`;
  const hits = ys.map((v, i) =>
    `<rect class="hit" data-i="${i}" x="${X(i) - 8}" y="${m.t}" width="16" height="${H - m.t - m.b}"/>`).join("");

  host.innerHTML = `<svg viewBox="0 0 ${W} ${H}" width="${W}" height="${H}">
    ${grid}${labels}
    <line class="baseline" x1="${m.l}" x2="${W - m.r}" y1="${H - m.b}" y2="${H - m.b}"/>
    <text x="${m.l}" y="${H - 8}">exp 1</text>
    <text x="${W - m.r}" y="${H - 8}" text-anchor="end">exp ${xs.length}</text>
    <path class="line" d="${path}"/>${markers}${hits}
  </svg>`;

  host.querySelectorAll(".hit").forEach((r) => {
    r.addEventListener("mousemove", (ev) => {
      const i = +r.dataset.i, e = exps[i];
      tooltip.show(
        `<div class="tt-k">experiment ${i + 1}</div>
         <div><span class="tt-v">${e.val_bpb.toFixed(4)}</span> val_bpb</div>
         ${e.desc || e.description ? `<div class="tt-k">${(e.desc || e.description).slice(0, 120)}</div>` : ""}`,
        ev.clientX, ev.clientY);
    });
    r.addEventListener("mouseleave", () => tooltip.hide());
  });
}

/* ---------------- checkpoint harness ---------------- */

function renderHarness() {
  const jtests = state.snapshot.jtests || {};
  const branches = Object.keys(jtests);
  const filter = $("#branch-filter");
  filter.innerHTML = branches.map((b) =>
    `<button data-b="${b}" class="${b === state.branch ? "active" : ""}">${b}</button>`).join("");
  filter.querySelectorAll("button").forEach((btn) =>
    btn.addEventListener("click", () => { state.branch = btn.dataset.b; renderHarness(); }));

  const rows = jtests[state.branch] || [];
  const mode = rows[0]?.mode;
  $("#harness-note").textContent = mode ? `mode: ${mode}${mode === "mock" ? " — scores are harness plumbing checks, not model capability" : ""}` : "";
  $("#jtest-table tbody").innerHTML = rows.map((t) => `
    <tr>
      <td><strong>${t.test}</strong></td>
      <td><span class="desc">${t.desc || ""}</span></td>
      <td class="num">${t.metric != null ? Number(t.metric).toFixed(3) : "—"}</td>
      <td>${statusChip(!!t.pass)}</td>
    </tr>`).join("");
}

/* ---------------- evaluations ---------------- */

function renderEvals() {
  const f = state.snapshot.frontier || { domains: [] };
  $("#evals-note").textContent =
    `judge: ${f.judge ?? "—"} · mode: ${f.mode ?? "—"}${f.mode === "mock" ? " — pipeline check, not model capability" : ""}`;
  const host = $("#frontier-chart");
  const domains = f.domains || [];
  if (!domains.length) { host.innerHTML = `<div class="empty">No frontier results in snapshot.</div>`; return; }

  const W = Math.max(640, host.clientWidth || 640);
  const rowH = 34, m = { l: 110, r: 64, t: 6, b: 24 };
  const H = m.t + m.b + domains.length * rowH;
  const X = (v) => m.l + v * (W - m.l - m.r);

  let grid = "";
  for (const v of [0, 0.25, 0.5, 0.75, 1]) {
    grid += `<line class="gridline" x1="${X(v)}" x2="${X(v)}" y1="${m.t}" y2="${H - m.b}"/>
      <text x="${X(v)}" y="${H - 6}" text-anchor="middle">${v}</text>`;
  }
  const bars = domains.map((d, i) => {
    const y = m.t + i * rowH + 6, h = rowH - 12;
    const w = Math.max(2, X(d.overall) - X(0));
    return `<text x="${m.l - 10}" y="${y + h / 2 + 4}" text-anchor="end">${d.domain}</text>
      <rect class="bar" data-i="${i}" x="${X(0)}" y="${y}" width="${w}" height="${h}" rx="4"
        role="button" aria-label="${d.domain} overall ${d.overall}"/>
      <text class="val-label" x="${X(0) + w + 8}" y="${y + h / 2 + 4}">${d.overall.toFixed(3)}</text>`;
  }).join("");

  host.innerHTML = `<svg viewBox="0 0 ${W} ${H}" width="${W}" height="${H}">
    ${grid}<line class="baseline" x1="${X(0)}" x2="${X(0)}" y1="${m.t}" y2="${H - m.b}"/>${bars}
  </svg>`;

  host.querySelectorAll(".bar").forEach((bar) => {
    bar.addEventListener("click", () => {
      host.querySelectorAll(".bar").forEach((b) => b.classList.remove("active"));
      bar.classList.add("active");
      showRubric(domains[+bar.dataset.i]);
    });
    bar.addEventListener("mousemove", (ev) => {
      const d = domains[+bar.dataset.i];
      tooltip.show(
        `<div class="tt-k">${d.domain} · ${d.task_id}</div>
         <div><span class="tt-v">${d.overall.toFixed(3)}</span> overall — click for rubric</div>`,
        ev.clientX, ev.clientY);
    });
    bar.addEventListener("mouseleave", () => tooltip.hide());
  });
}

function showRubric(domain) {
  $("#rubric-card").classList.remove("hidden");
  $("#rubric-title").textContent = `Per-rubric breakdown — ${domain.domain} (${domain.task_id})`;
  $("#rubric-table tbody").innerHTML = (domain.per_rubric || []).map((r) => `
    <tr><td>${r.category}</td>
    <td class="num">${r.weight != null ? r.weight.toFixed(3) : "—"}</td>
    <td class="num">${r.score != null ? r.score.toFixed(3) : "—"}</td></tr>`).join("");
}

/* ---------------- model cards ---------------- */

function renderCards() {
  const cards = state.cards?.cards || [];
  $("#cards-grid").innerHTML = cards.map((c) => {
    const a = c.architecture || {};
    const phases = c.training_data?.curriculum || [];
    const totalTokens = phases.reduce((s, p) => s + (p.tokens || 0), 0);
    const strip = phases.map((p) =>
      `<span style="flex:${Math.max(1, p.tokens || 1)}" title="${p.phase}: ${fmtTokens(p.tokens)}"></span>`).join("");
    const statusKind = c.status.startsWith("trained") ? "good"
      : c.status.startsWith("training") ? "warning" : "critical";
    return `<article class="mcard">
      <h2>${c.name} <span class="params">${c.params_label} params · rung ${c.ladder_rung}</span></h2>
      <div class="status-line">${chip(statusKind, c.status)}</div>
      <h3>Architecture</h3>
      <dl>
        <dt>Type</dt><dd>${a.type ?? "—"}</dd>
        <dt>d_model / heads</dt><dd>${a.d_model ?? "—"} / ${a.n_heads ?? "—"}</dd>
        <dt>Layers (t/f/r)</dt><dd>${a.layers?.text ?? "—"} / ${a.layers?.fusion ?? "—"} / ${a.layers?.reasoning ?? "—"}</dd>
        <dt>Vocab</dt><dd>${a.vocab_size ?? "—"}</dd>
        <dt>Workspaces</dt><dd>${a.workspaces ?? "—"}</dd>
      </dl>
      <h3>Training data — ${fmtTokens(totalTokens)} across ${phases.length} phases</h3>
      <div class="phase-strip">${strip}</div>
      <div class="phase-legend">${phases.map((p) => p.phase).join(" → ")}</div>
      <h3>Provenance</h3>
      <ul><li>${c.training_data?.provenance ?? ""}</li></ul>
      <h3>Constraints</h3>
      <ul>${(c.constraints || []).map((x) => `<li>${x}</li>`).join("")}</ul>
      <h3>Evaluation</h3>
      <ul><li>${c.evaluation?.harness ?? ""}</li></ul>
    </article>`;
  }).join("");
}

function fmtTokens(n) {
  if (!n) return "0";
  if (n >= 1e9) return (n / 1e9).toFixed(1) + "B tokens";
  if (n >= 1e6) return (n / 1e6).toFixed(1) + "M tokens";
  return (n / 1e3).toFixed(0) + "K tokens";
}

/* ---------------- shell ---------------- */

function switchView(name) {
  document.querySelectorAll(".view").forEach((v) => v.classList.add("hidden"));
  $(`#view-${name}`).classList.remove("hidden");
  document.querySelectorAll(".tab").forEach((t) => {
    const active = t.dataset.view === name;
    t.classList.toggle("active", active);
    t.setAttribute("aria-selected", String(active));
  });
}

function initTheme() {
  const saved = localStorage.getItem("arxiviq_theme");
  if (saved) document.documentElement.dataset.theme = saved;
  $("#theme-toggle").addEventListener("click", () => {
    const cur = document.documentElement.dataset.theme
      || (matchMedia("(prefers-color-scheme: dark)").matches ? "dark" : "light");
    const next = cur === "dark" ? "light" : "dark";
    document.documentElement.dataset.theme = next;
    localStorage.setItem("arxiviq_theme", next);
    renderAll(); // charts re-read CSS vars via classes; re-render for width changes
  });
}

function renderAll() {
  renderTelemetry();
  renderHarness();
  renderEvals();
  renderCards();
}

async function main() {
  tooltip.el = $("#tooltip");
  initTheme();
  document.querySelectorAll(".tab").forEach((t) =>
    t.addEventListener("click", () => switchView(t.dataset.view)));
  await loadBaked();
  renderSourceBadge();
  renderAll();
  await tryLive();
  renderTelemetry();
  setInterval(async () => { await tryLive(); renderTelemetry(); }, POLL_MS);
  window.addEventListener("resize", () => { renderBpbChart(state.live.experiments || []); renderEvals(); });
}

main().catch((err) => {
  $("#source-badge").textContent = "data load failed";
  console.error(err);
});
